import{_ as n,C as o,o as i,c as r,j as s,a as t,E as h,ao as l}from"./chunks/framework.ucUddl5u.js";const b=JSON.parse('{"title":"Going remote","description":"","frontmatter":{},"headers":[],"relativePath":"start/remote.md","filePath":"start/remote.md","lastUpdated":null}'),d={name:"start/remote.md"};function c(p,e,u,k,g,m){const a=o("DemoLoop");return i(),r("div",null,[e[0]||(e[0]=s("h1",{id:"Going-remote",tabindex:"-1"},[t("Going remote "),s("a",{class:"header-anchor",href:"#Going-remote","aria-label":'Permalink to "Going remote {#Going-remote}"'},"​")],-1)),e[1]||(e[1]=s("p",null,[t("The "),s("strong",null,"backend daemon"),t(" runs where your GPUs and data are, the "),s("strong",null,"frontend"),t(" window runs on the machine in front of you, and the two talk over SSH: the launcher forwards the backend's socket, and browser pages ride that same connection. If the frontend closes, the agents and the REPL keep running on the server.")],-1)),h(a,{name:"sessions",caption:"Session rows and their work-state colours."}),e[2]||(e[2]=l('<h2 id="1.-Install-the-backend-on-the-server" tabindex="-1">1. Install the backend on the server <a class="header-anchor" href="#1.-Install-the-backend-on-the-server" aria-label="Permalink to &quot;1. Install the backend on the server {#1.-Install-the-backend-on-the-server}&quot;">​</a></h2><p>On the server (Linux), install the headless backend role:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/kalidke/ship-of-tools/main/scripts/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --be-only</span></span></code></pre></div><p>By default this installs and starts the <code>systemd --user</code> unit <code>sotd.service</code>, so the daemon outlives your SSH login. (<code>--no-service</code> skips the unit when a shared-home deployment supervises <code>sotd</code> itself; see <a href="./install">Install details</a>.)</p><p>Every role needs Julia 1.12 or newer (installed with juliaup if missing) and gets the skills and hooks; see <a href="/ship-of-tools/dev/start/install#install-footprint">What the installer changes</a>.</p><p>If the server&#39;s home directory is itself on NFS, point the daemon&#39;s state root at local disk first — see <a href="/ship-of-tools/dev/guide/troubleshooting#A-session-will-not-start-on-a-shared-home">A session will not start on a shared home</a>.</p><h2 id="2.-Install-the-frontend-on-your-machine" tabindex="-1">2. Install the frontend on your machine <a class="header-anchor" href="#2.-Install-the-frontend-on-your-machine" aria-label="Permalink to &quot;2. Install the frontend on your machine {#2.-Install-the-frontend-on-your-machine}&quot;">​</a></h2><p>On the laptop or desktop, install the frontend role and name the server by its SSH alias (the one you use for <code>ssh myserver</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/kalidke/ship-of-tools/main/scripts/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myserver</span></span></code></pre></div><p>On Windows, use the release zip and <code>scripts\\install-shortcut.ps1</code>, as described under <a href="./install">Install</a>.</p><h2 id="3.-Launch" tabindex="-1">3. Launch <a class="header-anchor" href="#3.-Launch" aria-label="Permalink to &quot;3. Launch {#3.-Launch}&quot;">​</a></h2><p>Run <code>sot-launch</code> (or the desktop entry). The launcher opens the SSH forwards to the backend, applies any staged update, and starts the frontend. The daemon on the server is started once and survives across launches. On Linux and macOS the SSH forwards run in the background and outlive the window; a later launch reuses them.</p><p>With more than one server, the frontend connects to every backend host listed in <code>hosts.toml</code>. One machine, the <em>hub</em>, holds the canonical copy, and <code>sotd topology sync</code> fetches it on every launch; see <a href="/ship-of-tools/dev/guide/modes#hosts-mode">Hosts mode</a> and <a href="./../ref/config">Configuration files</a>.</p><h2 id="Reconnecting" tabindex="-1">Reconnecting <a class="header-anchor" href="#Reconnecting" aria-label="Permalink to &quot;Reconnecting {#Reconnecting}&quot;">​</a></h2><p>The connection can drop (laptop sleep, network change, SSH timeout) without losing anything on the server. The frontend reconnects on its own; <strong><code>F5</code></strong> retries at once. Agent sessions do not depend on the connection: each runs under its own supervisor on the server (see <a href="./../concepts/sessions">Sessions and persistence</a>).</p><h2 id="Browser-pages" tabindex="-1">Browser pages <a class="header-anchor" href="#Browser-pages" aria-label="Permalink to &quot;Browser pages {#Browser-pages}&quot;">​</a></h2><p><code>o</code> opens HTML, video and Pluto pages in your own browser, <code>Shift+W</code> opens a file&#39;s built documentation site, and <code>wglshow</code> opens an interactive WGLMakie figure. These work the same with a remote backend and need no extra SSH setup. How the traffic is carried is described under <a href="/ship-of-tools/dev/guide/repl#Interactive-figures-in-the-browser">Interactive figures in the browser</a>.</p><h2 id="Next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#Next-steps" aria-label="Permalink to &quot;Next steps {#Next-steps}&quot;">​</a></h2><ul><li><p><a href="./../guide/second-frontend">A second frontend</a> — attach a desktop and a laptop to the same backend.</p></li><li><p><a href="./../guide/enrolling">Enrolling a host</a> — make a server reachable from every frontend.</p></li><li><p><a href="./../guide/troubleshooting">Troubleshooting</a> — when a launch or a browser page does not come up.</p></li></ul>',19))])}const v=n(d,[["render",c]]);export{b as __pageData,v as default};
